import {
  Field,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldSet,
} from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";
import { PasswordInput } from "@/registry/erbium/ui/password-input";

const FieldInput = () => (
  <div className="w-full max-w-md">
    <FieldSet>
      <FieldGroup>
        <Field>
          <FieldLabel>Username</FieldLabel>
          <Input type="text" placeholder="Jane Doe" />
          <FieldDescription>Choose a unique username for your account.</FieldDescription>
        </Field>
        <Field>
          <FieldLabel>Password</FieldLabel>
          <FieldDescription>Must be at least 8 characters long.</FieldDescription>
          <PasswordInput autoComplete="new-password" placeholder="••••••••" />
        </Field>
      </FieldGroup>
    </FieldSet>
  </div>
);

export default FieldInput;

import ExampleFieldInput from "../examples/field-input";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleFieldInput />
  </div>
);

export default Example;
